import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"搜尋記錄","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 搜尋記錄（Search History）","slug":"_1-搜尋記錄-search-history","link":"#_1-搜尋記錄-search-history","children":[]},{"level":2,"title":"2. 關鍵字記錄（Keyword History）","slug":"_2-關鍵字記錄-keyword-history","link":"#_2-關鍵字記錄-keyword-history","children":[]},{"level":2,"title":"3. 查詢關聯（Query Associations）","slug":"_3-查詢關聯-query-associations","link":"#_3-查詢關聯-query-associations","children":[]}],"relativePath":"zh-HK/user-guide/settings/history.md","filePath":"zh-HK/user-guide/settings/history.md","lastUpdated":1792776074000}`),a={name:`zh-HK/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="搜尋記錄" tabindex="-1">搜尋記錄 <a class="header-anchor" href="#搜尋記錄" aria-label="Permalink to “搜尋記錄”">​</a></h1><p>搜尋記錄頁面透過三個相互獨立的標籤頁管理使用頻率、輸入詞條與跨名關聯：<strong>搜尋記錄</strong>、<strong>關鍵字記錄</strong>與<strong>查詢關聯</strong>。</p><h2 id="_1-搜尋記錄-search-history" tabindex="-1">1. 搜尋記錄（Search History） <a class="header-anchor" href="#_1-搜尋記錄-search-history" aria-label="Permalink to “1. 搜尋記錄（Search History）”">​</a></h2><p>搜尋記錄按路徑統計實際開啟過的檔案、資料夾與應用程式的使用頻率和最近時間：</p><ul><li><strong>同級衰減微調</strong>：高頻使用的項目按 90 天半衰期計算有效分，僅在<strong>同一文字比對等級內</strong>優先排列，絕不會越過完整或更乾淨的直接名稱命中。</li><li><strong>內嵌視窗智慧分區</strong>：在檔案選取對話方塊的內嵌搜尋中，當前資料夾內項目歸入「當前資料夾」，其餘歸入「全域搜尋」，同層內直接命中始終排在學習關聯之前。</li><li><strong>失效路徑自動過濾</strong>：被移動或刪除的路徑在檢索時自動跳過，保證列表不重複、無死鏈。</li><li><strong>管理操作</strong>：支援<strong>啟用記錄功能</strong>總開關、關鍵字過濾、<strong>清除少於等於 N 次的記錄</strong>、單筆刪除、<strong>清空全部記錄</strong>以及即時自動更新。</li></ul><h2 id="_2-關鍵字記錄-keyword-history" tabindex="-1">2. 關鍵字記錄（Keyword History） <a class="header-anchor" href="#_2-關鍵字記錄-keyword-history" aria-label="Permalink to “2. 關鍵字記錄（Keyword History）”">​</a></h2><p>關鍵字記錄記憶實際執行過結果或動作，或用於開啟完整視窗的<strong>原始查詢字串</strong>。僅輸入關鍵字後關閉快速搜尋視窗不會新增記錄：</p><ul><li><strong>快速鍵快速翻閱</strong>：在快速搜尋視窗中可使用快速鍵 <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> 翻閱最近搜尋詞，按 <strong><code>Ctrl+Delete</code></strong> 直接刪除當前詞彙。</li><li><strong>獨立清理維護</strong>：提供獨立的啟用開關、搜尋過濾、按次數門檻清理、單筆刪除與清空全部功能。</li></ul><h2 id="_3-查詢關聯-query-associations" tabindex="-1">3. 查詢關聯（Query Associations） <a class="header-anchor" href="#_3-查詢關聯-query-associations" aria-label="Permalink to “3. 查詢關聯（Query Associations）”">​</a></h2><p>查詢關聯獨立儲存已確認的 <strong>查詢詞 → 目標路徑</strong> 習慣映射，與路徑使用頻率完全分離：</p><ul><li><strong>3 次自然開啟門檻</strong>：同一規範化查詢詞下至少<strong>自然開啟 3 次</strong>後，才會在後續輸入時補充召回該目標，避免偶爾誤按一次就長期污染結果。</li><li><strong>阻斷自強化與尾部補充</strong>：點擊由查詢關聯補充出的項目不會反向自增未確認計數，不召回低優先級快取路徑，且始終排在直接文字命中之後。</li><li><strong>獨立清理</strong>：可隨時篩選、單筆刪除或清空全部查詢關聯，而不會重設路徑使用頻率。</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};